// src/components/Topbar.js
import React from 'react';
import './Topbar.css';
import { FaBell, FaPlus, FaUserCircle, FaSearch } from 'react-icons/fa';

const Topbar = () => {
  return (
    <div className="topbar">
      <div className="topbar-left">
        <h2>MediVault Pro</h2>
      </div>

      <div className="topbar-center">
        <div className="search-box">
          <FaSearch className="search-icon" />
          <input type="text" placeholder="Search patient, report..." />
        </div>
      </div>

      <div className="topbar-right">
        <button className="quick-action"><FaPlus /> Create</button>
        <div className="icon-btn"><FaBell /></div>
        <div className="profile-box">
          <FaUserCircle className="profile-icon" />
          <span>Dr. Priyanshu</span>
        </div>
      </div>
    </div>
  );
};

export default Topbar;
